<script setup>import PartnerLayout from '@/Layouts/PartnerLayout.vue';import FormErrors from '@/Components/Partner/FormErrors.vue';import {Link,useForm} from '@inertiajs/vue3';const props=defineProps({ticket:Object});const form=useForm({message:''});</script><template><PartnerLayout :title="ticket.subject"><Link :href="route('partner.support')" class="text-cyan-700">Back to support</Link><p class="my-5">{{ ticket.ticket_number }} ? {{ ticket.customer.name }} ? {{ ticket.status }}</p><article v-for="message in ticket.messages" :key="message.id" class="mb-4 rounded-xl bg-white p-5"><h2 class="font-bold">{{ message.sender?.name || 'Support team' }}</h2><p class="mt-3 whitespace-pre-line">{{ message.body }}</p></article><form v-if="ticket.status!=='closed'" class="form-card" @submit.prevent="form.post(route('partner.support.reply',ticket.uuid),{preserveScroll:true,onSuccess:()=>form.reset()})"><FormErrors :errors="form.errors"/><label>Your reply<textarea v-model="form.message" rows="5" required minlength="2" maxlength="20000"/></label><button class="form-button" :disabled="form.processing">Send reply</button></form></PartnerLayout></template>
